private TreeNode<T> rotateRight(TreeNode<T> node) {
    TreeNode<T> parent = node.getParent();
    TreeNode<T> child = node.getLeftChild();
    if (parent == null || child == null) {
        return node;
    }
    node.setLeftChild(child.getRightChild());
