            File[] files = f.listFiles();
            for (File file : files) {
                if (file.isFile() && file.getName().endsWith(".jar")) {
                    cpV.add(file.toURI().toURL());
                }
            }
        }
    } catch (Exception e) {
        e.printStackTrace();
    }
}

