public void doGet(HttpServletRequest request, HttpServletResponse response) throws ServletException, IOException {
    String queryString = request.getQueryString();
    if (queryString == null) {
        throw new ServletException("Missing query string");
    }

    Map<String, String> params = new HashMap<>();
    for (String param : queryString.split("&")) {
        String[] keyValue = param.split("=");
        if (keyValue.length != 2) {
            throw new ServletException("Invalid query string");
        }
        params.put(keyValue[0], keyValue[1]);
    }

    String name = params.get("name");
    if (name == null) {
        throw new ServletException("Missing name parameter");
    }

    String title = params.get("title");
    if (title == null) {
        throw new ServletException("Missing title parameter");
    }

    String content = params.get("content");
    if (content == null) {
        throw new ServletException("Missing content parameter");
    }

    Article article = new Article(name, title, content);
    request.setAttribute("article", article);
    RequestDispatcher dispatcher = request.getRequestDispatcher("article.jsp");
