    StringBuilder buf = new StringBuilder(str.length());
    int i = 0;
    while (i < str.length()) {
        char c = str.charAt(i++);
        if (c == '\\') {
            if (i == str.length()) {
                buf.append('\\');
            } else {
                c = str.charAt(i++);
                switch (c) {
                    case 'n':
                        buf.append('\n');
                        break;
                    case 'r':
                        buf.append('\r');
                        break;
                    case 't':
                        buf.append('\t');
                        break;
                    case 'b':
                        buf.append('\b');
                        break;
                    case 'f':
                        buf.append('\f');
                        break;
                    case 'u':
                        if (i + 4 <= str.length()) {
                            String hex = str.substring(i, i + 4);
                            i += 4;
                            try {
                                int val = Integer.parseInt(hex, 16);
                                buf.append((char) val);
                            } catch (NumberFormatException nfe) {
                                buf.append('\\');
                                buf.append('u');
                                buf.append(hex);
                            }
                        } else {
                            buf.append('\\');
                            buf.append('u');
                        }
                        break;
                    case '/':
                    case '\\':
                    case '\'':
                    case '\"':
                        buf.append(c);
                        break;
                    default:
                        buf.append('\\');
                        buf.append(c);
                        break;
                }
            }
        } else {
            buf.append(c);
        }
    }
    return buf.toString();
}

